// If APIs for Employees, Users, and Products return different data shapes, // we need to define separate interfaces for each API.

interface Product { id: number; name: string; price: number; }

interface User { id: number; name: string; email: string; }

interface Challan { challanNumber: string; amount: number; }

// Without Generics: We need to write separate methods for each API.

getProducts(): Observable<Product[]> { return this.http.get<Product[]>('/api/products'); }

getUsers(): Observable<User[]> { return this.http.get<User[]>('/api/users'); }

getChallans(): Observable<Challan[]> { return this.http.get<Challan[]>('/api/challans'); }

// With Generics: Instead of writing the same code repeatedly, // we can create one reusable generic method.

getData<T>(url: string): Observable<T> { return this.http.get<T>(url); }

// Reuse the same method by passing different types.

this.getData<Product[]>('/api/products'); this.getData<User[]>('/api/users'); this.getData<Challan[]>('/api/challans');

